'use strict';
let messageLink='',messageInspect=true,pairCode=null,connectedDevices=[];
let quickLinkDraft='',quickMessageDraft='';
const quickDraftHome=home;
home=function(){return quickDraftHome().replace('id="quick-link"',`id="quick-link" value="${esc(quickLinkDraft)}"`).replace(/(<textarea[^>]*id="quick-message"[^>]*>)[\s\S]*?(<\/textarea>)/,(_all,start,end)=>start+esc(quickMessageDraft)+end);};
document.addEventListener('input',event=>{if(event.target.id==='quick-link')quickLinkDraft=event.target.value;if(event.target.id==='quick-message')quickMessageDraft=event.target.value;});
const plainMessagePage=messagePage;
messagePage=function(){let html=plainMessagePage();html=html.replace('<div class="form-row"><label class="field-label" for="message-context">',`<div class="form-row"><label class="field-label" for="message-link">${t('Link received with the message','संदेश के साथ मिला लिंक')} <span class="optional">${t('(optional)','(वैकल्पिक)')}</span></label><input id="message-link" maxlength="2048" type="url" placeholder="https://… or upi://pay?…" ${messageBusy?'disabled':''} value="${esc(messageLink)}"><label class="inspect-choice"><input id="message-inspect-link" type="checkbox" ${messageInspect?'checked':''} ${messageBusy?'disabled':''}>${t('Inspect the public page behind this link','इस लिंक का सार्वजनिक पेज पढ़ें')}</label><p class="microcopy">${t('Reads public HTML/text without signing in or running scripts. Do not submit password-reset or private account links.','सार्वजनिक पाठ पढ़ता है; साइन-इन या स्क्रिप्ट नहीं चलती। पासवर्ड रीसेट या निजी खाता लिंक न भेजें।')}</p></div><div class="form-row"><label class="field-label" for="message-context">`);html=html.replace('minlength="3" required','minlength="3"');return html;};
const messageOnlyAPI=api;
api=async function(path,method='GET',body){if(path==='/analyze-message'&&body)body={...body,link:messageLink.trim(),inspect_link:messageInspect};return messageOnlyAPI(path,method,body);};
const textOnlyCheck=checkMessage;
checkMessage=async function(){messageLink=$('#message-link')?.value.trim()??messageLink;messageInspect=$('#message-inspect-link')?.checked??messageInspect;if(!($('#scam-message')?.value.trim()||messageDraft.trim())&&messageLink){messageDraft='Please assess this link and its public page.';if($('#scam-message'))$('#scam-message').value=messageDraft;}return textOnlyCheck();};
function submitQuickCheck(form){const data=new FormData(form),link=String(data.get('link')||'').trim(),message=String(data.get('message')||'').trim();if(!link&&!message){toast(t('Paste a link, a message, or both.','लिंक, संदेश या दोनों पेस्ट करें।'));$('#quick-link')?.focus();return;}messageDraft=message||(link?'Please assess this link and its public page.':'');messageLink=link;messageInspect=true;messageContext='Submitted with Quick check on the home page.';messageResult=null;messageError='';view='consumer';navigate('messages');checkMessage();}
const clearTextMessage=actions['clear-message'];
actions['clear-message']=()=>{messageLink='';messageInspect=true;clearTextMessage();};
const oldContentResult=contentResult;
contentResult=function(result){let html=oldContentResult(result);const info=result.link_inspection;if(info){const fetched=info.status==='fetched',status=fetched?t('Public page read','सार्वजनिक पेज पढ़ा गया'):info.status==='upi_details'?t('UPI details decoded','UPI विवरण पढ़ा गया'):t('Page content not read','पेज का विवरण नहीं पढ़ा गया');const section=`<section class="link-report"><h3>${icon(fetched?'checkCircle':'info')}${status}</h3><p>${esc(info.reason)}</p>${info.checked_at?`<small>Checked ${new Date(info.checked_at*1000).toLocaleString()}</small>`:''}${info.title?`<strong>${esc(info.title)}</strong>`:''}<dl><dt>${t('Submitted link','दिया गया लिंक')}</dt><dd>${esc(info.url)}</dd>${info.final_url?`<dt>${t('Final destination','अंतिम पता')}</dt><dd>${esc(info.final_url)}</dd>`:''}${info.redirects?.length>1?`<dt>Redirects</dt><dd>${info.redirects.length-1}</dd>`:''}</dl>${info.truncated?'<p>Only a bounded text excerpt was analyzed.</p>':''}</section>`;html=html.replace('<h3>'+t('What to do next','अगले कदम')+'</h3>',section+'<h3>'+t('What to do next','अगले कदम')+'</h3>');}if(result.cached)html=html.replace('<div class="result-kicker">',`<p class="microcopy">Reused the saved check from ${Number(result.cached_age_seconds||0)} seconds ago.</p><div class="result-kicker">`);return html;};
const existingReadLink=readLink;
readLink=function(value){let url;try{url=new URL(value.trim());}catch{return existingReadLink(value);}if(['https:','http:'].includes(url.protocol)&&url.hostname!=='pay.demo'){messageDraft='Please assess this link and its public page.';messageLink=value.trim();messageInspect=true;messageContext='User-submitted link.';messageResult=null;view='consumer';navigate('messages');return false;}return existingReadLink(value);};
const oldCompanionSettings=settings;
settings=function(){return oldCompanionSettings()+`<div class="flow-container"><section class="card settings-group"><h2>${t('Keep UPI Guard beside you','UPI Guard अपने साथ रखें')}</h2><p class="settings-copy">${t('Use a floating helper on websites and above normal Windows apps. Checks run only when you click. Connect each device using a one-time code; no OpenAI key is stored in either client.','वेबसाइट और Windows ऐप के ऊपर फ्लोटिंग सहायक रखें। जाँच आपके क्लिक पर होती है। हर डिवाइस को एक बार के कोड से जोड़ें; OpenAI कुंजी क्लाइंट में नहीं रहती।')}</p><div class="button-row"><a class="btn secondary" href="/downloads/upi-guard-extension.zip" download>Download Chrome/Edge extension</a><a class="btn secondary" href="/downloads/upi-guard-windows.zip" download>Download Windows companion</a></div><details class="explain"><summary>Installation & privacy</summary><p>Extension: extract the ZIP, open chrome://extensions or edge://extensions, enable Developer mode, choose Load unpacked and select the extracted folder. Website access lets the floating button appear on ordinary HTTP/HTTPS pages. Browser settings pages, extension stores and some protected pages cannot host it. Select a message and click the shield, use the right-click menu, or explicitly check the page.</p><p>Windows: extract the ZIP and run Start UPI Guard.vbs. Python 3 with Tk is required; this laptop already has it. The draggable shield stays above normal windows. Select text and click the shield to copy and check it; if copying is unavailable, paste into its panel. Secure desktop and some exclusive full-screen apps cannot be overlaid.</p><p>Only a user-requested selection or page excerpt is sent to your backend and OpenAI. Public links can be fetched without cookies. There is no passive screen recording, inbox monitoring or keystroke logging. Connections expire in 30 days and can be revoked below. Free-backend restarts can invalidate connections.</p></details><div class="button-row">${btn(t('Create connection code','कनेक्शन कोड बनाएँ'),'pair-companion','','link')}${btn(t('Refresh connected devices','जुड़े डिवाइस देखें'),'refresh-devices','secondary','refresh')}</div>${pairCode?`<div class="pair-code"><small>ONE-TIME CODE · expires ${new Date(pairCode.expires_at*1000).toLocaleTimeString()}</small><strong>${esc(pairCode.code)}</strong><p>Enter it only in your UPI Guard extension or Windows companion. Each client needs a fresh code.</p>${btn('Copy code','copy-pair-code','secondary')}</div>`:''}<div id="connected-devices">${connectedDevices.length?connectedDevices.map(d=>`<div class="device-row"><span><strong>${esc(d.name)}</strong><small>Expires ${new Date(d.expires_at*1000).toLocaleDateString()}</small></span><button class="text-link" data-revoke-device="${esc(d.id)}">Disconnect</button></div>`).join(''):'<p class="microcopy">Refresh to see connected companions.</p>'}</div></section></div>`;};
actions['pair-companion']=()=>mutate(async()=>{pairCode=await api('/companion/pair','POST',{});render();});
actions['copy-pair-code']=async()=>{try{await navigator.clipboard.writeText(pairCode?.code||'');toast('Connection code copied.');}catch{toast('Select and copy the displayed code.');}};
actions['refresh-devices']=()=>mutate(async()=>{connectedDevices=(await api('/companion/devices')).devices;render();});
document.addEventListener('click',event=>{const button=event.target.closest('[data-revoke-device]');if(button)mutate(async()=>{await api('/companion/revoke','POST',{device_id:button.dataset.revokeDevice});connectedDevices=(await api('/companion/devices')).devices;render();toast('Companion disconnected.');});});
document.addEventListener('input',event=>{if(event.target.id==='message-link'){messageLink=event.target.value;messageResult=null;$('#content-result')?.remove();}});
document.addEventListener('change',event=>{if(event.target.id==='message-inspect-link'){messageInspect=event.target.checked;messageResult=null;$('#content-result')?.remove();}});
render();

const qrMessageWithLink=actions['qr-as-message'];actions['qr-as-message']=()=>{const r=lastContentResult?.kind==='qr'?lastContentResult:qrResult;messageLink=/^(https?:|upi:)/i.test(r?.payload||'')?r.payload.slice(0,2048):'';messageInspect=true;qrMessageWithLink();render();};

if(new URLSearchParams(location.search).get('companion')==='connect'){view='consumer';page='settings';render();}
